	private static final class Highlight
	{
		BossRegistry.Boss boss;
		String item;
		double ratio;
		int detail; // dry-streak length, or for a hit the KC gap it landed in (kills since the previous one)
		boolean ongoing; // true when the streak hasn't ended yet
		double pct; // % of players who would have the drop within that many kills
	}

	BufferedImage renderOverviewCard()
	{
		List<BossRegistry.Boss> all = BossRegistry.all();

		boolean showUnknown = plugin.showUnknownKc();
		long grandTotal = 0;
		long totalDrops = 0;
		int uniquesObtained = 0;
		Map<BossRegistry.Boss, Long> gpByBoss = new HashMap<>();
		BossRegistry.Boss highestKcBoss = null;
		int highestKc = 0;
		Highlight curDry = null;
		Highlight allDry = null;
		Highlight lucky = null;

		for (BossRegistry.Boss b : all)
		{
			int kc = plugin.getKc(b);
			// With imports hidden, a boss Lucky Log has never seen a kill for (numbers from a
			// collection-log import or Set KC only) stays out of Highest KC and the dry cards;
			// its tracked gp and per-unique history are empty anyway.
			boolean eligible = showUnknown || plugin.hasTrackedKills(b);
			// Salvage is sorted by the thousand; it would sit on Highest KC forever.
			if (eligible && kc > highestKc && !BossRegistry.isSalvage(b))
			{
				highestKc = kc;
				highestKcBoss = b;
			}
			long gp = 0;
			for (ItemTotal t : plugin.getTotals(b))
			{
				gp += plugin.unitPrice(t.id) * t.total;
				totalDrops += t.count;
			}
			if (gp > 0)
			{
				gpByBoss.put(b, gp);
				grandTotal += gp;
			}
			for (BossRegistry.Drop d : b.notableDrops())
			{
				List<Integer> gotKcs = plugin.getUniqueKcs(b, d.name);
				uniquesObtained += gotKcs.size() + (showUnknown ? plugin.getUnknownCount(b, d.name) : 0);
				if (d.oneInX <= 0)
				{
					continue;
				}
				// current dry streak on this unique — also counts toward all-time,
				// so all-time driest can never show less dry than the current streak.
				// Items owned only via collection-log import have unknown obtain KCs:
				// count from the import-time KC if recorded, otherwise skip them —
				// an item the player already owns must never headline "driest".
				// Pets and one-time uniques already owned have no streak at all: the
				// game stopped rolling them the moment they dropped.
				if (eligible && kc > 0 && !plugin.doneForever(b, d))
				{
					int baseline = plugin.getLastDropKc(b, d.name);
					int unknown = plugin.getUnknownCount(b, d.name);
					if (unknown > 0 && gotKcs.isEmpty())
					{
						int ib = plugin.importBaselineKc(b, d.name);
						baseline = ib < 0 ? -1 : Math.max(baseline, ib);
					}
					if (baseline >= 0)
					{
						int since = kc - baseline;
						double ratio = since / d.oneInX;
						if (since > 0 && (curDry == null || ratio > curDry.ratio))
						{
							curDry = highlight(b, d.name, ratio, since, true, pctByNow(d.oneInX, since));
						}
						if (since > 0 && (allDry == null || ratio > allDry.ratio))
						{
							allDry = highlight(b, d.name, ratio, since, true, pctByNow(d.oneInX, since));
						}
					}
				}
				// historical gaps between hits
				int prev = 0;
				for (int k : gotKcs)
				{
					int gap = k - prev;
					prev = k;
					if (gap < 1)
					{
						continue;
					}
					double ratio = gap / d.oneInX;
					if (allDry == null || ratio > allDry.ratio)
					{
						allDry = highlight(b, d.name, ratio, gap, false, pctByNow(d.oneInX, gap));
					}
					if (d.oneInX >= 20 && (lucky == null || ratio < lucky.ratio))
					{
						lucky = highlight(b, d.name, ratio, gap, false, pctByNow(d.oneInX, gap));
					}
				}
			}
		}

		List<Map.Entry<BossRegistry.Boss, Long>> top = new ArrayList<>(gpByBoss.entrySet());
		top.sort((a, c) -> Long.compare(c.getValue(), a.getValue()));
		if (top.size() > 5)
		{
			top = top.subList(0, 5);
		}

		Set<Integer> ids = new LinkedHashSet<>();
		addHighlightIcon(ids, curDry);
		addHighlightIcon(ids, allDry);
		addHighlightIcon(ids, lucky);
		Map<Integer, BufferedImage> sprites = loadSprites(ids);

		BufferedImage img = new BufferedImage(W, H, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		paintBase(g);
		paintHeader(g, "OVERVIEW");

		int bx = 40;
		bx = statBlock(g, bx, 116, "TOTAL LOOT TRACKED", fmtGp(grandTotal), valColor(grandTotal));
		bx = statBlock(g, bx, 116, "DROPS TRACKED", String.format("%,d", totalDrops), CREAM);
		statBlock(g, bx, 116, "UNIQUES OBTAINED", String.format("%,d", uniquesObtained), uniquesObtained > 0 ? GREEN : CREAM);

		// three highlight panels
		int pw = 362;
		int ph = 150;
		int py = 190;
		paintHighlight(g, 40, py, pw, ph, "CURRENT DRIEST", DRY_RED, curDry, sprites,
			curDry == null ? null : String.format("%,d dry · %.1f%% of players would have it", curDry.detail, curDry.pct));
		paintHighlight(g, 40 + pw + 17, py, pw, ph, "ALL-TIME DRIEST", new Color(0xe8, 0xa8, 0x5c), allDry, sprites,
			allDry == null ? null : String.format(allDry.ongoing
				? "%,d and counting · %.1f%% would have it"
				: "went %,d · %.1f%% would have it", allDry.detail, allDry.pct));
		paintHighlight(g, 40 + (pw + 17) * 2, py, pw, ph, "LUCKIEST HIT", GREEN, lucky, sprites,
			lucky == null ? null : String.format("went %,d · only %.1f%% would have it by then", lucky.detail, lucky.pct));

		// top 5 most profitable bosses
		g.setFont(bold(17f));
		g.setColor(GOLD);
		g.drawString("TOP 5 MOST PROFITABLE BOSSES", 40, 386);
		long maxGp = top.isEmpty() ? 1 : top.get(0).getValue();
		int ry = 402;
		for (int i = 0; i < top.size(); i++)
		{
			BossRegistry.Boss b = top.get(i).getKey();
			long gp = top.get(i).getValue();
			int y = ry + i * 44;
			// proportional bar behind the row
			g.setColor(new Color(0xd4, 0xaf, 0x5e, 26));
			int barW = (int) Math.max(6, 620.0 * gp / maxGp);
			g.fillRoundRect(40, y, barW, 38, 8, 8);
			g.setFont(bold(18f));
			g.setColor(GOLD);
			g.drawString(String.valueOf(i + 1), 52, y + 25);
			BufferedImage bi = plugin.bossImage(b);
			if (bi != null)
			{
				drawFitted(g, bi, 74, y + 2, 34, 34);
			}
			g.setFont(bold(17f));
			g.setColor(CREAM);
			drawTruncated(g, b.shortName(), 118, y + 25, 380);
			g.setFont(bold(17f));
			g.setColor(valColor(gp));
			drawRight(g, fmtGp(gp), 660, y + 25);
		}
		if (top.isEmpty())
		{
			g.setFont(plain(15f));
			g.setColor(GREY);
			g.drawString("No loot tracked yet.", 40, 420);
		}

		// highest KC panel, bottom right
		g.setFont(bold(17f));
		g.setColor(GOLD);
		g.drawString("HIGHEST KC", 700, 386);
		if (highestKcBoss != null)
		{
			g.setColor(PANEL);
			g.fillRoundRect(700, 398, 460, 180, 14, 14);
			g.setColor(PANEL_LINE);
			g.drawRoundRect(700, 398, 460, 180, 14, 14);
			BufferedImage bi = plugin.bossImage(highestKcBoss);
			if (bi != null)
			{
				drawFitted(g, bi, 724, 414, 130, 148);
			}
			g.setFont(bold(26f));
			g.setColor(CREAM);
			drawTruncated(g, highestKcBoss.shortName(), 874, 462, 270);
			g.setFont(bold(40f));
			g.setColor(GOLD);
			g.drawString(String.format("%,d", highestKc), 874, 512);
			g.setFont(plain(14f));
			g.setColor(GREY);
			g.drawString(isReward(highestKcBoss) ? "reward pulls" : "kill count", 874, 534);
		}

		paintFooter(g);
		g.dispose();
		return img;
	}

	private static Highlight highlight(BossRegistry.Boss b, String item, double ratio, int detail, boolean ongoing, double pct)
	{
		Highlight h = new Highlight();
		h.boss = b;
		h.item = item;
		h.ratio = ratio;
		h.detail = detail;
		h.ongoing = ongoing;
		h.pct = pct;
		return h;
	}

	/** % of players who would have hit a 1/oneInX drop at least once within n attempts. */
	private static double pctByNow(double oneInX, int n)
	{
		if (oneInX <= 0 || n <= 0)
		{
			return 0;
		}
		// cap so extreme streaks never display a literal "100.0%"
		return Math.min(99.9, 100.0 * (1.0 - Math.pow(1.0 - 1.0 / oneInX, n)));
	}

	private void addHighlightIcon(Set<Integer> ids, Highlight h)
	{
		if (h != null)
		{
			int id = plugin.iconId(h.item);
			if (id > 0)
			{
				ids.add(id);
			}
		}
	}

	private void paintHighlight(Graphics2D g, int x, int y, int w, int h, String title, Color accent,
		Highlight hl, Map<Integer, BufferedImage> sprites, String detail)
	{
		g.setColor(PANEL);
		g.fillRoundRect(x, y, w, h, 14, 14);
		g.setColor(PANEL_LINE);
		g.drawRoundRect(x, y, w, h, 14, 14);
		g.setColor(accent);
		g.fillRoundRect(x, y, w, 4, 4, 4);
		g.setFont(bold(15f));
		g.setColor(accent);
		g.drawString(title, x + 18, y + 32);
		if (hl == null)
		{
			g.setFont(plain(14f));
			g.setColor(GREY);
			g.drawString("Not enough data yet", x + 18, y + 70);
			return;
		}
		BufferedImage sp = sprites.get(plugin.iconId(hl.item));
		if (sp != null)
		{
			drawFitted(g, sp, x + 18, y + 46, 42, 42);
		}
		g.setFont(bold(18f));
		g.setColor(CREAM);
		drawTruncated(g, hl.item, x + 72, y + 62, w - 90);
		g.setFont(plain(14f));
		g.setColor(GREY);
		drawTruncated(g, hl.boss.shortName(), x + 72, y + 82, w - 90);
		g.setFont(bold(18f));
		g.setColor(accent);
		drawTruncated(g, detail, x + 18, y + 120, w - 36);
	}

