	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		BossRegistry.Boss boss = BossRegistry.byLootName(event.getName());
		if (boss == null)
		{
			return;
		}

		// Doom fires one loot event per completed delve level, with the level as
		// metadata — credit that floor's unique odds before recording any drops,
		// so a unique received this floor snapshots after the roll it came from.
		if ("Doom of Mokhaiotl".equals(boss.display) && event.getMetadata() instanceof Integer)
		{
			recordDoomDelve((Integer) event.getMetadata());
		}

		rememberName();
		int kc = getKc(boss) + 1;
		setKc(boss, kc);

		List<LootEntry.Item> items = new ArrayList<>();
		Map<Integer, ItemTotal> totals = getTotalsMap(boss);
		if (event.getItems() != null)
		{
			for (ItemStack is : event.getItems())
			{
				String itemName;
				try
				{
					itemName = client.getItemDefinition(is.getId()).getName();
				}
				catch (Exception ex)
				{
					continue;
				}
				items.add(new LootEntry.Item(is.getId(), itemName, is.getQuantity()));
				valueCache.put(is.getId(), safePrice(is.getId()));
				iconIdCache.put(itemName.toLowerCase(), is.getId());
				ItemTotal t = totals.get(is.getId());
				if (t == null)
				{
					t = new ItemTotal(is.getId(), itemName);
					totals.put(is.getId(), t);
				}
				t.total += is.getQuantity();
				t.count++;
				for (BossRegistry.Drop d : boss.drops)
				{
					if (d.notable && d.name.equalsIgnoreCase(itemName))
					{
						addUniqueKc(boss, d.name, kc);
						setRaidSnap(boss, d.name);
					}
				}
			}
		}
		saveTotals(boss, totals);
		List<LootEntry> hist = getHistory(boss);
		hist.add(new LootEntry(kc, items));
		saveHistory(boss, hist);

		// pair with a pet message that arrived just before this loot
		if (petPairer.onLoot(boss, client.getTickCount()) != null)
		{
			recordPet(boss);
		}

		SwingUtilities.invokeLater(() -> panel.onKill(boss));
	}

	/** Record the boss's pet as obtained at the current KC (unique history, totals, loot feed). */
	private void recordPet(BossRegistry.Boss boss)
	{
		BossRegistry.Drop pet = null;
		for (BossRegistry.Drop d : boss.drops)
		{
			if (d.pet)
			{
				pet = d;
				break;
			}
		}
		if (pet == null)
		{
			return;
		}
		int kc = getKc(boss);
		addUniqueKc(boss, pet.name, kc);
		setRaidSnap(boss, pet.name);

		int id = iconId(pet.name);
		if (id > 0)
		{
			Map<Integer, ItemTotal> totals = getTotalsMap(boss);
			ItemTotal t = totals.get(id);
			if (t == null)
			{
				t = new ItemTotal(id, pet.name);
				totals.put(id, t);
			}
			t.total += 1;
			t.count++;
			saveTotals(boss, totals);

			List<LootEntry> hist = getHistory(boss);
			if (!hist.isEmpty() && hist.get(hist.size() - 1).kc == kc)
			{
				LootEntry last = hist.get(hist.size() - 1);
				if (last.items == null)
				{
					last.items = new ArrayList<>();
				}
				last.items.add(new LootEntry.Item(id, pet.name, 1));
				saveHistory(boss, hist);
			}
		}
		final String petName = pet.name;
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"Lucky Log: " + petName + " recorded at " + boss.shortName() + " KC " + kc + "!", null);
		SwingUtilities.invokeLater(() -> panel.onKill(boss));
	}

