	// ===== Doom of Mokhaiotl: per-item unique rate by delve level =====
	// index 0 = delve 2 ... index 7 = delve 9+ (deeper delves clamp to the last entry).
	// The loot tracker fires one LootReceived per completed delve level with the level
	// as metadata — each floor's bank-or-continue loot roll is credited as it happens.
	private static final double[] DOOM_ITEM_RATE = {2500, 2000, 1350, 810, 765, 720, 630, 540};
	private static final double[] DOOM_DOM_RATE = {0, 0, 0, 0, 1000, 750, 500, 250};

	// ===== Fortis Colosseum: overall unique chance per wave (waves 4..12) =====
	// Each wave's loot rolls when the wave is completed ("Wave N completed!" message),
	// whether the player banks or continues — so credit odds wave by wave.
	private static final double[] COLO_OVERALL = {124, 110, 96, 82, 68, 54, 40, 26, 12};
	private static final Pattern COLO_WAVE_MSG = Pattern.compile("^Wave (\\d+) completed! Wave duration");

	private void recordDoomDelve(int level)
	{
		BossRegistry.Boss b = BossRegistry.byLootName("Doom of Mokhaiotl");
		if (b == null || level < 2)
		{
			return;
		}
		int idx = Math.min(level, 9) - 2;
		double p = 1.0 / DOOM_ITEM_RATE[idx];
		double total = 0;
		total += addEsum(b, "Mokhaiotl cloth", p);
		if (level >= 3)
		{
			total += addEsum(b, "Eye of ayak (uncharged)", p);
		}
		if (level >= 4)
		{
			total += addEsum(b, "Avernic treads", p);
		}
		if (DOOM_DOM_RATE[idx] > 0)
		{
			total += addEsum(b, "Dom", 1.0 / DOOM_DOM_RATE[idx]);
		}
		pset("rsum_" + key(b), getRaidSum(b) + total);
		pset("rcnt_" + key(b), getRaidCount(b) + 1);
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rerender);
		}
	}

	private void recordColosseumWave(int wave)
	{
		BossRegistry.Boss b = BossRegistry.byLootName("Fortis Colosseum");
		if (b == null || wave < 1)
		{
			return;
		}
		double total = 0;
		if (wave >= 4)
		{
			double p = 1.0 / COLO_OVERALL[Math.min(wave, 12) - 4];
			double echo = wave <= 6 ? p * 0.4 : p * 6.0 / 16.0;
			double sunfire = wave <= 6 ? p * 0.6 : p * 9.0 / 16.0;
			double ralos = wave <= 6 ? 0 : p / 16.0;
			total += addEsum(b, "Echo crystal", echo);
			total += addEsum(b, "Sunfire fanatic helm", sunfire / 3.0);
			total += addEsum(b, "Sunfire fanatic cuirass", sunfire / 3.0);
			total += addEsum(b, "Sunfire fanatic chausses", sunfire / 3.0);
			if (ralos > 0)
			{
				total += addEsum(b, "Tonalztics of ralos", ralos);
			}
		}
		if (wave >= 12)
		{
			addEsum(b, "Smol heredit", 1.0 / 200.0);
		}
		pset("rsum_" + key(b), getRaidSum(b) + total);
		pset("rcnt_" + key(b), getRaidCount(b) + 1);
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rerender);
		}
	}

	// per-item expected-unique sums, for bosses whose rates change with depth/wave
	double getEsum(BossRegistry.Boss b, String item)
	{
		Double v = pget("esum_" + key(b) + "_" + dkey(item), Double.class);
		return v == null ? 0.0 : v;
	}

	private double addEsum(BossRegistry.Boss b, String item, double p)
	{
		pset("esum_" + key(b) + "_" + dkey(item), getEsum(b, item) + p);
		return p;
	}

	private double getEsnap(BossRegistry.Boss b, String item)
	{
		Double v = pget("esnap_" + key(b) + "_" + dkey(item), Double.class);
		return v == null ? 0.0 : v;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType t = event.getType();
		if (t != ChatMessageType.GAMEMESSAGE && t != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = Text.removeTags(event.getMessage());
		try
		{
			if (PetPairer.isPetMessage(msg))
			{
				BossRegistry.Boss petBoss = petPairer.onPetMessage(client.getTickCount());
				if (petBoss != null)
				{
					recordPet(petBoss);
				}
				else
				{
					onSkillPetMessage(client.getTickCount());
				}
				return;
			}
			Matcher wave = COLO_WAVE_MSG.matcher(msg);
			if (wave.find())
			{
				recordColosseumWave(Integer.parseInt(wave.group(1)));
				return;
			}
			if (msg.startsWith("Congratulations - your raid is complete"))
			{
				int pts = client.getVarpValue(4609); // RAIDS_PLAYERSCORE (personal CoX points)
				if (pts > 0)
				{
					recordRaid("Chambers of Xeric", clamp(pts, 0, 570000) / 867600.0);
				}
			}
			else if (msg.contains("completed Tombs of Amascut"))
			{
				int rl = client.getVarbitValue(14380);
				int slot = client.getVarbitValue(14354);
				int pts = (slot >= 0 && slot < 8) ? client.getVarbitValue(14346 + slot) : 0;
				double p = toaPurple(pts, rl);
				if (p > 0)
				{
					recordRaid("Tombs of Amascut", p);
				}
			}
			else if (msg.contains("completed Theatre of Blood"))
			{
				boolean hard = msg.contains("Hard Mode");
				recordRaid(hard ? "Theatre of Blood Hard Mode" : "Theatre of Blood", hard ? 1.0 / 7.7 : 1.0 / 9.1);
			}
		}
		catch (Exception ignored)
		{
		}
	}

	private static double clamp(double v, double lo, double hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}

	private double toaPurple(int points, int raidLevel)
	{
		if (points <= 0)
		{
			return -1;
		}
		double pts = Math.min(points, 64000);
		double erl = raidLevel <= 400 ? raidLevel : 400 + (Math.min(raidLevel, 550) - 400) / 3.0;
		double per1 = 10500 - 20 * erl;
		if (per1 <= 0)
		{
			return 0.55;
		}
		return Math.min(pts / (100.0 * per1), 0.55);
	}

	private void recordRaid(String raidDisplay, double p)
	{
		if (p <= 0)
		{
			return;
		}
		BossRegistry.Boss b = BossRegistry.byLootName(raidDisplay);
		if (b == null)
		{
			return;
		}
		pset("rsum_" + key(b), getRaidSum(b) + p);
		pset("rcnt_" + key(b), getRaidCount(b) + 1);
		SwingUtilities.invokeLater(() -> panel.onKill(b));
	}

	double getRaidSum(BossRegistry.Boss b)
	{
		Double v = pget("rsum_" + key(b), Double.class);
		return v == null ? 0.0 : v;
	}

	int getRaidCount(BossRegistry.Boss b)
	{
		Integer v = pget("rcnt_" + key(b), Integer.class);
