		if (cached != null)
		{
			return cached;
		}
		String path = "/com/pudgy/droptracker/bosses/" + k + ".png";
		if (getClass().getResource(path) == null)
		{
			return null;
		}
		try
		{
			BufferedImage img = ImageUtil.loadImageResource(getClass(), path);
			if (img != null)
			{
				bossImgCache.put(k, img);
			}
			return img;
		}
		catch (Exception e)
		{
			return null;
		}
	}
