	public static final class Drop
	{
		public final String name;
		public final double oneInX;
		public final boolean pet;
		public final boolean notable;
		public final String note;
		/** Stops dropping once obtained (the game no longer rolls it), e.g. the Whisperer's sirenic tablet. */
		public final boolean once;
		public Drop(String name, double oneInX, boolean pet, boolean notable, String note, boolean once)
		{
			this.name = name; this.oneInX = oneInX; this.pet = pet; this.notable = notable; this.note = note; this.once = once;
		}
		public Drop(String name, double oneInX, boolean pet, boolean notable, String note)
		{
			this(name, oneInX, pet, notable, note, false);
		}
		public Drop(String name, double oneInX)
		{
			this(name, oneInX, false, true, null);
		}
		public Drop(String name, double oneInX, boolean pet, String note)
		{
			this(name, oneInX, pet, true, note);
		}
		public static Drop common(String name, double oneInX)
		{
			return new Drop(name, oneInX, false, false, null);
		}
		/** A notable that the game only ever gives once; dry-streak maths stops the moment it is owned. */
		public static Drop once(String name, double oneInX)
		{
			return new Drop(name, oneInX, false, true, null, true);
		}
		/**
		 * False only for one-time uniques. Pets keep rolling after the first one (the game
		 * says "you would have been followed" instead of giving a second pet), so a pet dry
		 * streak stays meaningful and PetPairer keeps counting those messages.
		 */
		public boolean repeatable()
		{
			return !once;
		}
	}

	/** Salvage is sorted by the thousand, so it is kept off the Highest KC panel. */
	static boolean isSalvage(Boss b)
	{
		return b != null && b.display.toLowerCase().contains("salvage");
	}

	public static final class Boss
	{
		public final String display;
		public final List<Drop> drops;
		public Boss(String display, Drop... drops)
		{
			this.display = display;
			this.drops = Arrays.asList(drops);
		}

		/** Display name without a leading "The", for UI lists, sorting and cards. */
		public String shortName()
		{
			return display.regionMatches(true, 0, "The ", 0, 4) ? display.substring(4) : display;
		}

		public Double rateFor(String itemName)
		{
			for (Drop d : drops)
			{
				if (d.name.equalsIgnoreCase(itemName))
				{
					return d.oneInX;
				}
			}
			return null;
		}
		public List<Drop> notableDrops()
		{
			List<Drop> r = new ArrayList<>();
			for (Drop d : drops)
			{
				if (d.notable)
				{
					r.add(d);
				}
			}
			return r;
		}
	}

	private static final Map<String, Boss> BY_NAME = new LinkedHashMap<>();
	// Some sources fire LootReceived under a different name than the boss display (the killed NPC,
	// the reward chest, etc.). Map those alternate loot names onto the registry display name.
	private static final Map<String, String> ALIASES = new LinkedHashMap<>();
	private static void add(Boss b)
	{
		BY_NAME.put(b.display.toLowerCase(), b);
	}
	private static void alias(String lootName, String display)
	{
		ALIASES.put(lootName.toLowerCase(), display.toLowerCase());
	}
	public static Boss byLootName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String key = name.toLowerCase();
		Boss b = BY_NAME.get(key);
		if (b == null)
		{
			String a = ALIASES.get(key);
			if (a != null)
			{
				b = BY_NAME.get(a);
			}
		}
		if (b == null)
		{
			// UI uses shortName() (no leading "The"); map it back to the stored name
			b = BY_NAME.get("the " + key);
		}
		return b;
	}
	public static List<Boss> all()
	{
		List<Boss> l = new ArrayList<>(BY_NAME.values());
		l.sort((a, b) -> a.shortName().compareToIgnoreCase(b.shortName()));
		return l;
	}

	/** Alternate names (loot aliases) pointing at this boss, e.g. "Sol Heredit" for Fortis Colosseum. */
	public static List<String> searchAliases(Boss b)
	{
		List<String> out = new ArrayList<>();
		String target = b.display.toLowerCase();
		for (Map.Entry<String, String> e : ALIASES.entrySet())
		{
			if (e.getValue().equals(target))
			{
				out.add(e.getKey());
			}
		}
		return out;
	}

