	private static ImageIcon mailIcon()
	{
		int s = 22;
		BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xC8, 0xDD, 0xE9));
		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		int x0 = 2, y0 = 6, w = s - 4, h = 11;
		g.drawRoundRect(x0, y0, w, h, 3, 3);
		g.drawLine(x0, y0, x0 + w / 2, y0 + h / 2);
		g.drawLine(x0 + w, y0, x0 + w / 2, y0 + h / 2);
		g.dispose();
		return new ImageIcon(img);
	}

	private static ImageIcon starIcon()
	{
		int s = 12;
		BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double cx = s / 2.0, cy = s / 2.0, rOut = s / 2.0 - 0.5, rIn = rOut * 0.45;
		java.awt.geom.Path2D.Double star = new java.awt.geom.Path2D.Double();
		for (int i = 0; i < 10; i++)
		{
			double r = (i % 2 == 0) ? rOut : rIn;
			double a = -Math.PI / 2 + i * Math.PI / 5;
			double x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
			if (i == 0)
			{
				star.moveTo(x, y);
			}
			else
			{
				star.lineTo(x, y);
			}
		}
		star.closePath();
		g.setColor(new Color(0xFF, 0xD7, 0x00));
		g.fill(star);
		g.dispose();
		return new ImageIcon(img);
	}

	void rebuild()
	{
		updating = true;
		bossBox.removeAllItems();
		bossBox.addItem(SKILL_PETS);
		for (BossRegistry.Boss b : BossRegistry.all())
		{
			bossBox.addItem(b.shortName());
		}
		updating = false;
		if (bossBox.getItemCount() > 0)
		{
			selectBoss();
		}
	}

	private BossRegistry.Boss current()
	{
		Object s = bossBox.getSelectedItem();
		return s == null ? null : BossRegistry.byLootName((String) s);
	}

	private boolean skillPetsSelected()
	{
		return SKILL_PETS.equals(bossBox.getSelectedItem());
	}

	private void selectBoss()
	{
		if (skillPetsSelected())
		{
			updating = true;
			goalBox.removeAllItems();
			goalBox.addItem("(none)");
			updating = false;
			refresh();
			return;
		}
		BossRegistry.Boss b = current();
		if (b == null)
		{
			return;
		}
		updating = true;
		goalBox.removeAllItems();
		goalBox.addItem("(none)");
		String goal = plugin.getGoal(b);
		boolean goalStillNotable = false;
		for (BossRegistry.Drop d : b.notableDrops())
		{
			goalBox.addItem(d.name);
			if (d.name.equals(goal))
			{
				goalStillNotable = true;
			}
		}
		// A goal saved before its drop was demoted out of notableDrops() is no longer in the
		// dropdown, so setSelectedItem would silently leave the box on "(none)" while the
		// header kept rendering the goal block from b.drops. Clear it instead.
		if (goal != null && !goalStillNotable)
		{
			plugin.setGoal(b, null);
			goal = null;
		}
		goalBox.setSelectedItem(goal == null ? "(none)" : goal);
		updating = false;
		plugin.warmPrices(b);
		refresh();
	}

	private void selectGoal()
	{
		BossRegistry.Boss b = current();
		if (b == null)
		{
			return;
		}
		Object g = goalBox.getSelectedItem();
		plugin.setGoal(b, (g == null || "(none)".equals(g)) ? null : (String) g);
		refresh();
	}

