	private void onSearch()
	{
		if (updating)
		{
			return;
		}
		String s = searchField.getText().trim().toLowerCase();
		java.util.List<String> starts = new java.util.ArrayList<>();
		java.util.List<String> contains = new java.util.ArrayList<>();
		for (BossRegistry.Boss b : BossRegistry.all())
		{
			String dl = b.shortName().toLowerCase();
			boolean aliasHit = false;
			if (!s.isEmpty() && !dl.contains(s))
			{
				for (String alias : BossRegistry.searchAliases(b))
				{
					if (alias.contains(s))
					{
						aliasHit = true;
						break;
					}
				}
			}
			if (s.isEmpty() || dl.startsWith(s))
			{
				starts.add(b.shortName());
			}
			else if (dl.contains(s) || aliasHit)
			{
				contains.add(b.shortName());
			}
		}
		starts.addAll(contains);
		if (s.isEmpty() || "skilling pets".contains(s) || s.startsWith("pet"))
		{
			starts.add(0, SKILL_PETS);
		}
		updating = true;
		bossBox.removeAllItems();
		for (String d : starts)
		{
			bossBox.addItem(d);
		}
		boolean any = bossBox.getItemCount() > 0;
		if (any)
		{
			bossBox.setSelectedIndex(0);
		}
		updating = false;
		if (any)
		{
			selectBoss();
		}
	}

	void onKill(BossRegistry.Boss b)
	{
		Object sel = bossBox.getSelectedItem();
		if (sel != null && b.shortName().equals(sel))
		{
			refresh();
			return;
		}
		updating = true;
		searchField.setText("");
		bossBox.removeAllItems();
		bossBox.addItem(SKILL_PETS);
		for (BossRegistry.Boss bb : BossRegistry.all())
		{
			bossBox.addItem(bb.shortName());
		}
		bossBox.setSelectedItem(b.shortName());
		updating = false;
		selectBoss();
	}

	void rerender()
	{
		refresh();
	}

