	/** boss == null renders the overview card; save == false copies to the clipboard. */
	private void makeCard(BossRegistry.Boss boss, boolean save)
	{
		makeCard(boss, save, false);
	}

	private void makeCard(BossRegistry.Boss boss, boolean save, boolean skillPets)
	{
		shareBtn.setEnabled(false);
		shareBtn.setText("Rendering…");
		plugin.snapshotForCards(boss, () ->
			new Thread(() ->
			{
				BufferedImage card = null;
				try
				{
					card = skillPets ? cardRenderer.renderSkillPetsCard()
						: boss != null ? cardRenderer.renderBossCard(boss) : cardRenderer.renderOverviewCard();
				}
				catch (Exception ex)
				{
					// fall through to "Failed" feedback
				}
				String feedback;
				if (card == null)
				{
					feedback = "Failed";
				}
				else if (save)
				{
					feedback = saveCard(card, boss);
				}
				else
				{
					feedback = copyCard(card);
				}
				String fb = feedback;
				javax.swing.SwingUtilities.invokeLater(() ->
				{
					shareBtn.setText(fb);
					new javax.swing.Timer(2500, ev ->
					{
						shareBtn.setText("Share Card");
						shareBtn.setEnabled(true);
					})
					{
						{
							setRepeats(false);
						}
					}.start();
				});
			}, "luckylog-card").start());
	}

	private static String copyCard(BufferedImage img)
	{
		try
		{
			java.awt.Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageSelection(img), null);
			return "Copied!";
		}
		catch (Exception e)
		{
			return "Failed";
		}
	}

	private static String saveCard(BufferedImage img, BossRegistry.Boss boss)
	{
		try
		{
			java.io.File dir = new java.io.File(net.runelite.client.RuneLite.SCREENSHOT_DIR, "lucky-log");
			if (!dir.exists() && !dir.mkdirs())
			{
				return "Failed";
			}
			String stem = boss != null ? DropTrackerPlugin.imgKey(boss.display) : "overview";
			java.io.File f = new java.io.File(dir, "luckylog-" + stem + "-" + System.currentTimeMillis() + ".png");
			javax.imageio.ImageIO.write(img, "png", f);
			return "Saved!";
		}
		catch (Exception e)
		{
			return "Failed";
		}
	}

	private static final class ImageSelection implements java.awt.datatransfer.Transferable
	{
		private final java.awt.Image image;

		private ImageSelection(java.awt.Image image)
		{
			this.image = image;
		}

		@Override
		public java.awt.datatransfer.DataFlavor[] getTransferDataFlavors()
		{
			return new java.awt.datatransfer.DataFlavor[]{java.awt.datatransfer.DataFlavor.imageFlavor};
		}

		@Override
		public boolean isDataFlavorSupported(java.awt.datatransfer.DataFlavor flavor)
		{
			return java.awt.datatransfer.DataFlavor.imageFlavor.equals(flavor);
		}

		@Override
		public Object getTransferData(java.awt.datatransfer.DataFlavor flavor) throws java.awt.datatransfer.UnsupportedFlavorException
		{
			if (!isDataFlavorSupported(flavor))
			{
				throw new java.awt.datatransfer.UnsupportedFlavorException(flavor);
			}
			return image;
		}
	}

	private static String fmt(double v)
	{
		if (!Double.isInfinite(v) && v == Math.floor(v))
		{
			return String.valueOf((long) v);
		}
		return String.format("%.1f", v);
	}

	private static String join(java.util.List<Integer> l)
	{
		StringBuilder s = new StringBuilder();
		for (int i = 0; i < l.size(); i++)
		{
			if (i > 0)
			{
				s.append(", ");
			}
			s.append(l.get(i));
		}
		return s.toString();
	}

	private static String fmtGp(long v)
	{
		if (v >= 10000000000L)
		{
			return String.format("%.1fB", v / 1000000000.0);
		}
		if (v >= 1000000000L)
		{
			return String.format("%.2fB", v / 1000000000.0);
		}
		if (v >= 1000000L)
		{
			return String.format("%.2fM", v / 1000000.0);
		}
		if (v >= 100000L)
		{
			return String.format("%.0fK", v / 1000.0);
		}
		if (v >= 1000L)
		{
			return String.format("%.1fK", v / 1000.0);
		}
		return String.valueOf(v);
	}

	private static String valHex(long v)
	{
		if (v >= 10000000000L)
		{
			return "#c068ff";
		}
		// 10B+  purple
		if (v >= 1000000000L)
		{
			return "#4da6ff";
		}
		// 1B+   blue
		if (v >= 1000000L)
		{
			return "#3fd14d";
		}
		// 1M+   green
		return "#ffffff";                            // <1M   white
	}

	private void setItemIcon(int id)
	{
		AsyncBufferedImage img = itemManager.getImage(id, 1, false);
		img.onLoaded(() ->
		{
			if (img.getWidth() <= 0 || img.getHeight() <= 0)
			{
				return;
			}
			imageLabel.setIcon(new ImageIcon(fitImage(img, 52, 52)));
		});
	}

	private static Image fitImage(BufferedImage img, int maxW, int maxH)
	{
		int w = img.getWidth(), hh = img.getHeight();
		double s = Math.min(maxW / (double) w, maxH / (double) hh);
		if (s == 1.0)
		{
			return img;
		}
		return img.getScaledInstance(Math.max(1, (int) Math.round(w * s)), Math.max(1, (int) Math.round(hh * s)), Image.SCALE_SMOOTH);
	}

	// white (0%) -> strong green (100%) for the dry-chance line
	private static String fadeWhiteToGreen(double p)
	{
		p = Math.max(0.0, Math.min(1.0, p));
		int r = (int) Math.round(255 + p * (60 - 255));
		int g = (int) Math.round(255 + p * (220 - 255));
		int bl = (int) Math.round(255 + p * (70 - 255));
		return String.format("#%02x%02x%02x", r, g, bl);
	}
}

